(function() {
  'use strict';

  class TurnAroundAdapter extends USF.SimulationAdapter {
    constructor() {
      super();
      this.name = 'TurnAround — Distressed Company Recovery';
      this.version = '1.1.0';
      this.ROUNDS = [
        {
          id: 1,
          theme: 'First 72 Hours',
          description: 'Immediate action is critical. You have $12M in available cash and 11 weeks until $65M matures. The bank standstill expires in 90 days. Focus on cash conservation and emergency stabilization.<br><br>What will you do in these critical first hours?',
          d1Label: 'Cash Preservation Strategy',
          d1Options: [
            { value: 1, label: 'Aggressive Freeze: Halt all non-essential spending immediately' },
            { value: 2, label: 'Moderate Cuts: Selective reduction of discretionary expenses' },
            { value: 3, label: 'Minimal Impact: Preserve current operations, minimal changes' }
          ],
          d2Label: 'Bank and Creditor Communication',
          d2Options: [
            { value: 1, label: 'Full Transparency: Disclose situation, request standstill extension' },
            { value: 2, label: 'Selective Disclosure: Share partial information, manage expectations' },
            { value: 3, label: 'Minimal Contact: Avoid detailed conversations for now' }
          ],
          d3Label: 'Immediate Cash Generation',
          d3Options: [
            { value: 1, label: 'Asset Liquidation: Sell non-core assets quickly' },
            { value: 2, label: 'Receivables Acceleration: Push customers to pay early' },
            { value: 3, label: 'Extend Payables: Negotiate longer payment terms with suppliers' }
          ]
        },
        {
          id: 2,
          theme: 'Operational Triage',
          description: 'The market is not improving. Viriato runs two plants in Brazil and Mexico. One is underutilized; one is reasonably efficient. Union agreements and customer supply chains complicate options.<br><br>How will you restructure operations?',
          d1Label: 'Plant Restructuring Decision',
          d1Options: [
            { value: 1, label: 'Close Both Plants: Outsource production, accept short-term pain' },
            { value: 2, label: 'Close One, Restructure One: Consolidate to Mexico facility' },
            { value: 3, label: 'Restructure Both: Modernize processes, reduce headcount moderately' }
          ],
          d2Label: 'Union and Employee Communication',
          d2Options: [
            { value: 1, label: 'Direct Engagement: Transparent about cuts, negotiate hard' },
            { value: 2, label: 'Phased Communication: Roll out changes gradually' },
            { value: 3, label: 'Delay Disclosure: Wait before announcing major changes' }
          ],
          d3Label: 'Supplier and Cost Management',
          d3Options: [
            { value: 1, label: 'Hardball Renegotiation: Demand 20-30% cost reductions' },
            { value: 2, label: 'Collaborative Approach: Work with suppliers on joint solutions' },
            { value: 3, label: 'Defer Payments: Extend payment terms to improve cash' }
          ]
        },
        {
          id: 3,
          theme: 'Creditor Negotiation',
          description: 'Operations are stabilizing, but the capital structure is the real problem. A hedge fund has acquired a blocking position. Creditors are demanding a restructuring plan.<br><br>What is your debt restructuring strategy?',
          d1Label: 'Debt Haircut Proposal',
          d1Options: [
            { value: 1, label: 'Large Haircut (40%): Bold restructuring, risk creditor rejection' },
            { value: 2, label: 'Moderate Haircut (25%): Balanced approach, credible to creditors' },
            { value: 3, label: 'Small Haircut (10%): Minimize dilution, maximize debt repayment' }
          ],
          d2Label: 'Hedge Fund and Equity Conversion Response',
          d2Options: [
            { value: 1, label: 'Accept Equity Conversion: Give 20% equity for debt relief' },
            { value: 2, label: 'Counter-Propose Hybrid: Offer 10% equity + conditional returns' },
            { value: 3, label: 'Reject Equity Conversion: Refuse dilution, pursue cash restructuring' }
          ],
          d3Label: 'Customer Supply Guarantee',
          d3Options: [
            { value: 1, label: 'Full Guarantee: Commit 100% on-time delivery going forward' },
            { value: 2, label: 'Conditional Guarantee: Commit with volume and price conditions' },
            { value: 3, label: 'No Guarantee: Maintain flexibility, compete on price only' }
          ]
        },
        {
          id: 4,
          theme: 'Stabilization Plan',
          description: 'The debt is restructured. Now you must prove the company can survive standalone. Headcount costs remain elevated. You need bridge financing to reach positive cash flow.<br><br>How will you lock in stabilization?',
          d1Label: 'Headcount Strategy',
          d1Options: [
            { value: 1, label: 'Deep Cuts (30%): Aggressive rightsizing, lean operations' },
            { value: 2, label: 'Moderate Cuts (15%): Selective reduction, preserve capability' },
            { value: 3, label: 'Minimal Cuts (5%): Protect talent, gradual optimization' }
          ],
          d2Label: 'Bridge Financing Approach',
          d2Options: [
            { value: 1, label: 'Large Bridge ($60M): Aggressive investment in turnaround' },
            { value: 2, label: 'Moderate Bridge ($35M): Conservative growth-focused approach' },
            { value: 3, label: 'Small Bridge ($15M): Minimal funding, tight financial management' }
          ],
          d3Label: 'Recovery Timeline and Targets',
          d3Options: [
            { value: 1, label: 'Aggressive 12-Month Plan: EBITDA positive by end of year' },
            { value: 2, label: 'Moderate 18-Month Plan: EBITDA positive in 6 quarters' },
            { value: 3, label: 'Conservative 24-Month Plan: Gradual, sustainable recovery' }
          ]
        }
      ];
    }

    initialize(state) {
      if (!state.domainState || Object.keys(state.domainState).length === 0) {
        state.domainState = {
          cash: 12000000,
          ebitda: -23750000,
          stakeholderConfidence: 30,
          liquidityScore: 45,
          operationalScore: 30,
          stakeholderScore: 30,
          coherenceScore: 40,
          turnAroundScore: 36.5, // 45*.30 + 30*.25 + 30*.25 + 40*.20 (was 36.25, inconsistent with the weights below)
          cashHistory: [],
          ebitdaHistory: [],
          confidenceHistory: [],
          scoreHistory: [],
          eventLog: '',
          insolvent: false,
          checkpoints: {}, // per-round pre-state snapshots for idempotent re-entry (v1.1.0)
          eventRolls: {}   // persisted crisis-event rolls so replays are deterministic (v1.1.0)
        };
      }
      if (!state.decisions || Object.keys(state.decisions).length === 0) {
        state.decisions = {
          strategy: 0,
          communication: 0,
          resource: 0
        };
      }
      this._updateBriefing(state);
    }

    validateDecisions(decisions) {
      var strategyEl = document.getElementById('strategySelect');
      var communicationEl = document.getElementById('communicationSelect');
      var resourceEl = document.getElementById('resourceSelect');

      if (strategyEl) decisions.strategy = parseInt(strategyEl.value);
      if (communicationEl) decisions.communication = parseInt(communicationEl.value);
      if (resourceEl) decisions.resource = parseInt(resourceEl.value);

      if (isNaN(decisions.strategy) || decisions.strategy < 1 || decisions.strategy > 3) {
        window.mySimulation.uiManager.showNotification(
          window.mySimulation.t('warning_strategy'), 'warning'
        );
        return false;
      }
      if (isNaN(decisions.communication) || decisions.communication < 1 || decisions.communication > 3) {
        window.mySimulation.uiManager.showNotification(
          window.mySimulation.t('warning_communication'), 'warning'
        );
        return false;
      }
      if (isNaN(decisions.resource) || decisions.resource < 1 || decisions.resource > 3) {
        window.mySimulation.uiManager.showNotification(
          window.mySimulation.t('warning_resource'), 'warning'
        );
        return false;
      }
      return true;
    }

    calculateResults(state) {
      var d = state.decisions;
      var currentRound = state.currentPeriod;
      var ds = state.domainState;

      // --- Idempotency guard (v1.1.0) -------------------------------------------------
      // Make calculateResults safe to call more than once for the same round
      // (double-submit, framework re-entry, or Undo-then-resubmit). On first entry we
      // checkpoint the pre-round state; on any re-entry we restore it, so score deltas,
      // cash/EBITDA changes and the four history-array pushes never compound.
      ds.checkpoints = ds.checkpoints || {};
      if (ds.checkpoints[currentRound]) {
        this._restore(ds, ds.checkpoints[currentRound], currentRound);
      } else {
        ds.checkpoints[currentRound] = this._snapshot(ds);
      }

      // --- Deterministic, persisted crisis-event roll (v1.1.0) ------------------------
      // Roll once per round and reuse it, so re-processing the same round yields the same
      // event (previously a live Math.random() re-rolled on every call -> non-reproducible).
      ds.eventRolls = ds.eventRolls || {};
      if (ds.eventRolls[currentRound] === undefined) {
        ds.eventRolls[currentRound] = Math.random();
      }
      var eventRoll = ds.eventRolls[currentRound];

      var liquidityDelta = 0;
      var operationalDelta = 0;
      var stakeholderDelta = 0;
      var coherenceDelta = 0;
      var cashDelta = 0;
      var ebitdaDelta = 0;
      var eventText = '';

      if (currentRound === 1) {
        if (d.strategy === 1) { liquidityDelta += 25; operationalDelta -= 5; stakeholderDelta += 5; cashDelta += 5000000; }
        else if (d.strategy === 2) { liquidityDelta += 15; operationalDelta += 5; stakeholderDelta += 10; cashDelta += 3000000; }
        else { liquidityDelta += 5; operationalDelta += 10; stakeholderDelta -= 5; cashDelta += 1000000; }

        if (d.communication === 1) { stakeholderDelta += 20; liquidityDelta += 5; }
        else if (d.communication === 2) { stakeholderDelta += 10; liquidityDelta += 3; }
        else { stakeholderDelta -= 10; }

        if (d.resource === 1) { liquidityDelta += 20; operationalDelta -= 10; cashDelta += 8000000; }
        else if (d.resource === 2) { liquidityDelta += 15; cashDelta += 5000000; }
        else { liquidityDelta += 10; stakeholderDelta -= 5; cashDelta += 3000000; }

        cashDelta -= 2000000;

        if (eventRoll < 0.4) {
          eventText = 'Major supplier threatens COD terms unless $8M overdue payment is received within 7 days. Operations will be severely impacted.';
          state.domainState.eventLog += '<br>Round 1 Event: Supplier COD threat (-$8M cash).';
          cashDelta -= 8000000;
          stakeholderDelta -= 10;
        }
      } else if (currentRound === 2) {
        if (d.strategy === 1) { operationalDelta += 25; stakeholderDelta -= 15; liquidityDelta += 15; ebitdaDelta += 8000000; cashDelta += 6000000; }
        else if (d.strategy === 2) { operationalDelta += 20; stakeholderDelta -= 5; liquidityDelta += 10; ebitdaDelta += 5000000; cashDelta += 4000000; }
        else { operationalDelta += 10; stakeholderDelta += 5; ebitdaDelta += 2000000; cashDelta -= 1000000; }

        if (d.communication === 1) { stakeholderDelta += 15; operationalDelta += 5; }
        else if (d.communication === 2) { stakeholderDelta += 10; operationalDelta += 3; }
        else { stakeholderDelta -= 10; operationalDelta -= 5; }

        if (d.resource === 1) { liquidityDelta += 15; stakeholderDelta -= 10; cashDelta += 4000000; }
        else if (d.resource === 2) { liquidityDelta += 10; stakeholderDelta += 10; cashDelta += 2000000; }
        else { liquidityDelta += 5; stakeholderDelta -= 5; cashDelta += 1000000; }

        cashDelta -= 1500000;

        if (eventRoll < 0.4) {
          eventText = 'Largest customer (25% of revenue) demands written supply assurance or will seek alternative suppliers. Risk losing $40M annual revenue.';
          state.domainState.eventLog += '<br>Round 2 Event: Customer supply assurance demand.';
          stakeholderDelta -= 15;
          operationalDelta -= 10;
        }
      } else if (currentRound === 3) {
        if (d.strategy === 1) { liquidityDelta += 20; stakeholderDelta -= 15; ebitdaDelta += 3000000; cashDelta += 8000000; }
        else if (d.strategy === 2) { liquidityDelta += 15; stakeholderDelta += 5; ebitdaDelta += 2000000; cashDelta += 5000000; }
        else { liquidityDelta += 5; stakeholderDelta += 15; cashDelta += 2000000; }

        if (d.communication === 1) { stakeholderDelta += 15; liquidityDelta += 10; cashDelta += 4000000; }
        else if (d.communication === 2) { stakeholderDelta += 10; liquidityDelta += 5; cashDelta += 2000000; }
        else { stakeholderDelta -= 15; liquidityDelta -= 5; cashDelta -= 2000000; }

        if (d.resource === 1) { stakeholderDelta += 20; liquidityDelta -= 10; cashDelta -= 10000000; }
        else if (d.resource === 2) { stakeholderDelta += 10; liquidityDelta -= 5; cashDelta -= 5000000; }
        else { stakeholderDelta -= 10; liquidityDelta += 5; cashDelta += 5000000; }

        cashDelta -= 1000000;

        if (eventRoll < 0.4) {
          eventText = 'Hedge fund has acquired 15% of senior debt and demands 20% equity stake. Failure to negotiate risks plan rejection by the syndicate.';
          state.domainState.eventLog += '<br>Round 3 Event: Hedge fund blocking position.';
          stakeholderDelta -= 20;
          coherenceDelta -= 10;
        }
      } else if (currentRound === 4) {
        if (d.strategy === 1) { operationalDelta += 20; stakeholderDelta -= 15; liquidityDelta += 15; ebitdaDelta += 6000000; cashDelta += 5000000; }
        else if (d.strategy === 2) { operationalDelta += 15; stakeholderDelta += 5; liquidityDelta += 5; ebitdaDelta += 4000000; cashDelta += 2000000; }
        else { operationalDelta += 5; stakeholderDelta += 10; ebitdaDelta += 1000000; cashDelta -= 1000000; }

        if (d.communication === 1) { liquidityDelta += 20; stakeholderDelta += 5; coherenceDelta += 5; cashDelta += 6000000; }
        else if (d.communication === 2) { liquidityDelta += 10; stakeholderDelta += 10; coherenceDelta += 10; cashDelta += 3500000; }
        else { liquidityDelta += 5; stakeholderDelta -= 5; coherenceDelta -= 5; cashDelta += 1500000; }

        if (d.resource === 1) { coherenceDelta += 20; stakeholderDelta -= 5; }
        else if (d.resource === 2) { coherenceDelta += 15; stakeholderDelta += 10; }
        else { coherenceDelta += 5; stakeholderDelta += 5; }

        cashDelta -= 500000;

        if (eventRoll < 0.4) {
          eventText = 'Restructuring advisor formally recommends preparing a pre-packaged bankruptcy filing as contingency if bridge financing fails.';
          state.domainState.eventLog += '<br>Round 4 Event: Pre-packaged bankruptcy recommendation.';
          coherenceDelta -= 15;
        }
      }

      state.domainState.liquidityScore = Math.max(0, Math.min(100, state.domainState.liquidityScore + liquidityDelta));
      state.domainState.operationalScore = Math.max(0, Math.min(100, state.domainState.operationalScore + operationalDelta));
      state.domainState.stakeholderScore = Math.max(0, Math.min(100, state.domainState.stakeholderScore + stakeholderDelta));
      state.domainState.coherenceScore = Math.max(0, Math.min(100, state.domainState.coherenceScore + coherenceDelta));

      state.domainState.cash += cashDelta;
      state.domainState.ebitda += ebitdaDelta;

      if ((currentRound === 1 || currentRound === 2) && state.domainState.cash <= 0) {
        state.domainState.insolvent = true;
        window.mySimulation.uiManager.showNotification(window.mySimulation.t('insolvency_warning'), 'danger');
      }

      state.domainState.turnAroundScore =
        state.domainState.liquidityScore * 0.30 +
        state.domainState.operationalScore * 0.25 +
        state.domainState.stakeholderScore * 0.25 +
        state.domainState.coherenceScore * 0.20;

      state.domainState.cashHistory.push(state.domainState.cash);
      state.domainState.ebitdaHistory.push(state.domainState.ebitda);
      state.domainState.confidenceHistory.push(state.domainState.stakeholderScore);
      state.domainState.scoreHistory.push(state.domainState.turnAroundScore);

      if (eventText) {
        var eventPanel = document.getElementById('eventPanel');
        var eventMessage = document.getElementById('eventMessage');
        if (eventPanel) eventPanel.style.display = 'block';
        if (eventMessage) eventMessage.innerHTML = eventText;
        window.mySimulation.uiManager.showNotification(window.mySimulation.t('event_triggered'), 'warning');
      } else {
        var eventPanelHide = document.getElementById('eventPanel');
        if (eventPanelHide) eventPanelHide.style.display = 'none';
      }

      var self = this;
      setTimeout(function() {
        self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: state.domainState });
      }, 500);

      return {
        period: currentRound,
        strategy: d.strategy,
        communication: d.communication,
        resource: d.resource,
        liquidityScore: state.domainState.liquidityScore,
        operationalScore: state.domainState.operationalScore,
        stakeholderScore: state.domainState.stakeholderScore,
        coherenceScore: state.domainState.coherenceScore,
        turnAroundScore: Math.round(state.domainState.turnAroundScore * 10) / 10,
        cash: state.domainState.cash,
        ebitda: state.domainState.ebitda,
        insolvent: state.domainState.insolvent
      };
    }

    setupUI(uiManager) {
      uiManager.bind('periodDisplay', 'currentPeriod');
      uiManager.bind('cashDisplay', 'domainState.cash',
