    getPerformanceSummary(history) {
      if (!history.length) return {};
      var last = history[history.length - 1];
      var results = last.results || {};
      var score = results.turnAroundScore || 0;
      var isInsolvent = results.insolvent || false;

      var performance = 'Beginner';
      if (isInsolvent) performance = 'Insolvent';
      else if (score >= 75) performance = 'Excellent';
      else if (score >= 60) performance = 'Good';
      else if (score >= 45) performance = 'Moderate';

      var insights = [];
      if (isInsolvent) {
        insights.push('Cash depleted before operational stabilization. Remember: cash first, operations second, capital structure third.');
      } else if (score >= 75) {
        insights.push('Strong turnaround execution. Balanced approach across liquidity, operations, and stakeholder management.');
      } else if (score >= 60) {
        insights.push('Solid foundation for recovery. Review stakeholder communication for further improvement.');
      } else {
        insights.push('Review the turnaround priority hierarchy: stabilize cash before restructuring operations or debt.');
      }

      return {
        totalScore: score,
        performance: performance,
        insights: insights,
        liquidityScore: results.liquidityScore || 0,
        operationalScore: results.operationalScore || 0,
        stakeholderScore: results.stakeholderScore || 0,
        coherenceScore: results.coherenceScore || 0
      };
    }

    getHint(state, results) {
      if (!results) return null;
      if (state.domainState.insolvent) return window.mySimulation.t('hint_insolvent');
      if (results.cash < 5000000 && state.currentPeriod <= 2) return window.mySimulation.t('hint_low_cash');
      if (results.stakeholderScore < 25) return window.mySimulation.t('hint_low_confidence');
      if (state.currentPeriod === 1) return window.mySimulation.t('hint_r1_complete');
      if (state.currentPeriod === 2) return window.mySimulation.t('hint_r2_complete');
      if (state.currentPeriod === 3) return window.mySimulation.t('hint_r3_complete');
      if (state.currentPeriod === 4) return window.mySimulation.t('hint_r4_complete');
      return null;
    }

