    // Capture the mutable scalar domain state before a round is applied (v1.1.0).
    // Plain data only, so domainState stays JSON-serializable.
    _snapshot(ds) {
      return {
        cash: ds.cash,
        ebitda: ds.ebitda,
        liquidityScore: ds.liquidityScore,
        operationalScore: ds.operationalScore,
        stakeholderScore: ds.stakeholderScore,
        coherenceScore: ds.coherenceScore,
        turnAroundScore: ds.turnAroundScore,
        eventLog: ds.eventLog,
        insolvent: ds.insolvent
      };
    }

    // Restore a per-round checkpoint and truncate the history arrays back to the rounds
    // completed before `round`, so a re-run of `round` produces identical state (v1.1.0).
    _restore(ds, snap, round) {
      ds.cash = snap.cash;
      ds.ebitda = snap.ebitda;
      ds.liquidityScore = snap.liquidityScore;
      ds.operationalScore = snap.operationalScore;
      ds.stakeholderScore = snap.stakeholderScore;
      ds.coherenceScore = snap.coherenceScore;
      ds.turnAroundScore = snap.turnAroundScore;
      ds.eventLog = snap.eventLog;
      ds.insolvent = snap.insolvent;
      var keep = round - 1;
      if (ds.cashHistory.length > keep) ds.cashHistory.length = keep;
      if (ds.ebitdaHistory.length > keep) ds.ebitdaHistory.length = keep;
      if (ds.confidenceHistory.length > keep) ds.confidenceHistory.length = keep;
      if (ds.scoreHistory.length > keep) ds.scoreHistory.length = keep;
    }

    _updateBriefing(state) {
      var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
      var round = this.ROUNDS[idx];

      var briefingPanel = document.getElementById('briefingPanel');
      if (briefingPanel) {
        var h2 = briefingPanel.querySelector('h2');
        if (h2) h2.textContent = 'Round ' + (idx + 1) + ': ' + round.theme;
        var content = document.getElementById('briefingContent');
        if (content) content.innerHTML = round.description;
      }

      var strategySelect = document.getElementById('strategySelect');
      var communicationSelect = document.getElementById('communicationSelect');
      var resourceSelect = document.getElementById('resourceSelect');

      if (strategySelect) {
        strategySelect.innerHTML = '<option value="">-- Select --</option>';
        round.d1Options.forEach(function(opt) {
          var option = document.createElement('option');
          option.value = opt.value;
          option.textContent = opt.label;
          strategySelect.appendChild(option);
        });
      }

      if (communicationSelect) {
        communicationSelect.innerHTML = '<option value="">-- Select --</option>';
        round.d2Options.forEach(function(opt) {
          var option = document.createElement('option');
          option.value = opt.value;
          option.textContent = opt.label;
          communicationSelect.appendChild(option);
        });
      }

      if (resourceSelect) {
        resourceSelect.innerHTML = '<option value="">-- Select --</option>';
        round.d3Options.forEach(function(opt) {
          var option = document.createElement('option');
          option.value = opt.value;
          option.textContent = opt.label;
          resourceSelect.appendChild(option);
        });
      }

      var strategyLabelEl = document.querySelector('label[for="strategySelect"]');
      var communicationLabelEl = document.querySelector('label[for="communicationSelect"]');
      var resourceLabelEl = document.querySelector('label[for="resourceSelect"]');
      if (strategyLabelEl) strategyLabelEl.textContent = round.d1Label;
      if (communicationLabelEl) communicationLabelEl.textContent = round.d2Label;
      if (resourceLabelEl) resourceLabelEl.textContent = round.d3Label;

      var eventPanel = document.getElementById('eventPanel');
      if (eventPanel) eventPanel.style.display = 'none';
    }
